/* Restricted math parser. Expressions are never evaluated as JavaScript. */
const mathFunctions={sin:Math.sin,cos:Math.cos,tan:Math.tan,asin:Math.asin,acos:Math.acos,atan:Math.atan,sinh:Math.sinh,cosh:Math.cosh,tanh:Math.tanh,sqrt:Math.sqrt,abs:Math.abs,exp:Math.exp,log:Math.log,ln:Math.log,log10:Math.log10,floor:Math.floor,ceil:Math.ceil,min:Math.min,max:Math.max};
function normalizeMath(input){let s=String(input).trim().replace(/^\$\$?|\$\$?$/g,'').replace(/\\\(|\\\)|\\\[|\\\]/g,'').replace(/\\left|\\right/g,'').replace(/\\(?:cdot|times)/g,'*').replace(/\\(?:,|;|!|quad|qquad)/g,' ').replace(/π/g,'pi').replace(/−|–/g,'-').replace(/×|·/g,'*').replace(/²/g,'^2').replace(/³/g,'^3');
let i=0;function group(){while(/\s/.test(s[i]||'')&&i<s.length)i++;if(s[i]!=='{')throw Error('LaTeX fractions and roots need braces, e.g. \\frac{1}{2}.');i++;let start=i,depth=1;while(i<s.length&&depth){if(s[i]==='{')depth++;if(s[i]==='}')depth--;i++}if(depth)throw Error('Close the LaTeX brace.');return s.slice(start,i-1)}let out='';while(i<s.length){if(s.slice(i,i+5)==='\\frac'){i+=5;let n=group(),d=group();out+='(('+normalizeMath(n)+')/('+normalizeMath(d)+'))'}else if(s.slice(i,i+5)==='\\sqrt'){i+=5;out+='sqrt('+normalizeMath(group())+')'}else if(s[i]==='\\'){i++;let match=s.slice(i).match(/^[a-zA-Z]+/);if(!match)throw Error('Unsupported LaTeX command.');let name=match[0];if(!(name in mathFunctions)&&name!=='pi')throw Error('Unsupported LaTeX command: '+name);out+=name;i+=name.length}else{out+=s[i++]} }return out.replace(/\{/g,'(').replace(/\}/g,')').replace(/^\s*[xyzPQR]\s*=\s*/,'')}
function parseMath(src,allowed=['x','y']){src=normalizeMath(src);let tokens=[],i=0;const words=Object.keys(mathFunctions).concat(['pi']).sort((a,b)=>b.length-a.length);while(i<src.length){if(/\s/.test(src[i])){i++;continue}let n=src.slice(i).match(/^(?:\d*\.\d+|\d+\.?\d*)(?:[eE][+-]?\d+)?/);if(n){tokens.push({type:'num',value:n[0]});i+=n[0].length;continue}let word=words.find(w=>src.startsWith(w,i));if(word){tokens.push({type:'id',value:word});i+=word.length;continue}let c=src[i++];if(/[a-zA-Z]/.test(c)){tokens.push({type:'id',value:c});continue}if('+-*/^(),|'.includes(c)){tokens.push({type:'op',value:c});continue}throw Error('Unrecognized symbol: '+c)}let p=0,peek=()=>tokens[p]?.value;function atom(){let t=tokens[p++];if(!t)throw Error('Enter an expression.');if(t.value==='+'||t.value==='-')return{type:'unary',op:t.value,arg:expr(3)};if(t.value==='('){let n=expr(0);if(peek()!==')')throw Error('Close the parenthesis.');p++;return n}if(t.type==='num')return{type:'number',value:Number(t.value)};if(t.type==='id'){if(Object.hasOwn(mathFunctions,t.value)){let args;if(peek()==='^'){p++;let power=atom();if(peek()!=='(')throw Error('Use parentheses after the function.');p++;args=[expr(0)];if(peek()!==')')throw Error('Close the function parenthesis.');p++;return{type:'binary',op:'^',left:{type:'call',name:t.value,args},right:power}}if(peek()!=='(')throw Error('Use '+t.value+'(…) for function arguments.');p++;args=[expr(0)];while(peek()===','){p++;args.push(expr(0))}if(peek()!==')')throw Error('Close the function parenthesis.');p++;if(!['min','max'].includes(t.value)&&args.length!==1)throw Error(t.value+' expects one argument.');return{type:'call',name:t.value,args}}if(![...allowed,'a','pi','e'].includes(t.value))throw Error('Unknown variable '+t.value+'. Use '+allowed.join(', ')+(allowed.length?' or a.':'constants only.'));return{type:'variable',name:t.value}}throw Error('Unexpected symbol: '+t.value)}
function expr(min){let left=atom();while(p<tokens.length){let op=peek(),prec={'+':1,'-':1,'*':2,'/':2,'^':4}[op],implicit=false;if(prec===undefined&&(tokens[p].type==='num'||tokens[p].type==='id'||op==='(')){op='*';prec=2;implicit=true}if(prec===undefined||prec<min)break;if(!implicit)p++;let right=expr(prec+(op==='^'?0:1));left={type:'binary',op,left,right}}return left}let ast=expr(0);if(p!==tokens.length)throw Error('Unexpected symbol: '+peek());return ast}
function evaluateMath(n,env){if(n.type==='number')return n.value;if(n.type==='variable')return n.name==='pi'?Math.PI:n.name==='e'?Math.E:n.name==='a'?a:env[n.name];if(n.type==='unary')return(n.op==='-'?-1:1)*evaluateMath(n.arg,env);if(n.type==='call')return mathFunctions[n.name](...n.args.map(x=>evaluateMath(x,env)));let l=evaluateMath(n.left,env),r=evaluateMath(n.right,env);return n.op==='+'?l+r:n.op==='-'?l-r:n.op==='*'?l*r:n.op==='/'?l/r:l**r}
function compile(src,allowed=['x','y']){let ast=parseMath(src,allowed);let fn=(x,y,z)=>evaluateMath(ast,{[allowed[0]]:x,[allowed[1]]:y,[allowed[2]]:z});fn.ast=ast;return fn}
function expressionPreview(src,vars){return'<math xmlns="http://www.w3.org/1998/Math/MathML">'+mathMarkup(parseMath(src,vars))+'</math>'}
/* Render the parsed tree with only the parentheses needed to preserve meaning. */
function mathMarkup(n,parent=0){const precedence=n.type==='binary'?({'+':1,'-':1,'*':2,'/':2,'^':4}[n.op]):n.type==='unary'?3:9;let out;if(n.type==='number')out='<mn>'+n.value+'</mn>';else if(n.type==='variable')out='<mi>'+(n.name==='pi'?'π':n.name)+'</mi>';else if(n.type==='unary')out='<mrow><mo>'+n.op+'</mo>'+mathMarkup(n.arg,3)+'</mrow>';else if(n.type==='call'){let args=n.args.map(x=>mathMarkup(x)).join('<mo>,</mo>');out=n.name==='sqrt'?'<msqrt>'+args+'</msqrt>':n.name==='abs'?'<mrow><mo>|</mo>'+args+'<mo>|</mo></mrow>':'<mrow><mi mathvariant="normal">'+n.name+'</mi><mo>(</mo>'+args+'<mo>)</mo></mrow>'}else if(n.op==='/')out='<mfrac>'+mathMarkup(n.left)+mathMarkup(n.right)+'</mfrac>';else if(n.op==='^')out='<msup>'+mathMarkup(n.left,5)+mathMarkup(n.right)+'</msup>';else out='<mrow>'+mathMarkup(n.left,precedence)+'<mo>'+(n.op==='*'?'⁢':n.op)+'</mo>'+mathMarkup(n.right,precedence+(n.op==='-'?1:0))+'</mrow>';return precedence<parent?'<mrow><mo>(</mo>'+out+'<mo>)</mo></mrow>':out}
